head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setTopRowIndex]<br/>Row 인덱스를 사용하여 특정 Row 가 Body 영역의 첫번째 Row 로 표시되게 세로 스크롤을 이동합니다.",
    "validation" : [
        "topRowIndex(필수) 파라미터로 Body 영역(뷰포트)의 첫번째 Row 로 표시할 Row 의 인덱스를 설정해야 합니다. (Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다)",
        "Row 인덱스를 사용하여 특정 Row 가 Body 영역의 첫번째 Row 로 표시되게 세로 스크롤을 이동해야 합니다.",
        "drawType='native' 인 경우 setTopRowIndex() 메소드는 동작하지 않습니다.",
        "noEvent(선택) 파라미터가 true 면 세로 스크롤이 최하단에 닿을때 onscrollend 이벤트를 발생시키지 않고, false(기본값)면 발생시켜야 합니다.",
        "autoFocus(선택) 파라미터가 true 면 메소드 실행 후 (0,0) 위치의 Cell 로 포커스를 이동하고, false(기본값)면 포커스를 이동하지 않아야 합니다.",
        "세로 스크롤을 최하단으로 이동해도 topRowIndex 파라미터에 해당하는 Row 가 첫번째 Row 가 되지 않으면 최대 스크롤 위치로 보정됩니다.",
        "topRowIndex 파라미터에 해당하는 Row 가 첫번째 Row 이면 setTopRowIndex() 메소드가 실행되지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // onscrollend 발생여부 플래그 초기화
    scwin.scrollEndFired = false;

    // 현재 조건(drawType) 라벨 표시
    $c.gcm.createLabel('label="drawType : ' + (con_drawType.getValue() || '(미설정)') + ' / 데이터 10 행, 디자인 높이 약 3~4 행 (뷰포트보다 데이터가 많아 세로 스크롤 발생)"', '', 'label1');

    // dataList 생성 (10 행 — 뷰포트보다 데이터가 많아 setTopRowIndex 로 세로 스크롤 이동 효과 확인 가능)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // 조건 설정 (drawType 미설정 시 '' → createCList 가 빈 문자열 속성을 제외하므로 Property 미설정 상태로 생성)
    let properties = {
        drawType: con_drawType.getValue(),
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 디자인 높이를 작게(약 3~4행) 설정 → 뷰포트에 일부 Row 만 표시되어 세로 스크롤이 발생, setTopRowIndex 이동 확인 가능
    // 마지막 컬럼 width='*' 로 가로 스크롤 방지
    // onscrollend 이벤트 바인딩 (noEvent 파라미터 검증용)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:171px;" ev:onscrollend="scwin.target1_onscrollend">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// onscrollend 핸들러 — 세로 스크롤이 최하단에 닿을때 발생 (noEvent=false 일 때 발생, noEvent=true 일 때 미발생)
scwin.target1_onscrollend = function (e) {
    scwin.scrollEndFired = true;
}



// setTopRowIndex 실행 — topRowIndex(par 값) Row 가 Body 영역의 첫번째 Row 로 표시되게 세로 스크롤 이동
// @param topRowIndex : 첫번째 Row 로 표시할 Row 인덱스 (0부터)
// @param noEvent  : true → onscrollend 미발생 / false(기본) → 발생
// @param autoFocus : true → 실행 후 (0,0) Cell 포커스 이동 / false(기본) → 미이동
// @return 없음. 이동은 렌더 의존값이므로 native setTimeout(500) 으로 갱신 후 getTopRowIndex()/getBottomRowIndex()/포커스/onscrollend 발생여부 확인
//  - 정상        : getTopRowIndex() == 설정값 (해당 Row 가 최상단)
//  - drawType=native : 미동작 (스크롤 불변)
//  - 9(끝, 첫번째 될 수 없음) : 최대 스크롤 위치로 보정 (getTopRowIndex()<9, getBottomRowIndex()=9)
//  - 0(이미 첫번째) : 미실행 (변화 없음)
scwin.btn_setTopRowIndex_onclick = function (e) {
    let topRowIndex = Number(par_topRowIndex.getValue());
    let noEvent = (par_noEvent.getText() === 'true');
    let autoFocus = (par_autoFocus.getText() === 'true');

    // 호출 전 상태
    let beforeTop = target1.getTopRowIndex();
    let beforeBottom = target1.getBottomRowIndex();
    scwin.scrollEndFired = false;

    // setTopRowIndex 실행 (noEvent, autoFocus 파라미터 전달)
    // setTopRowIndex(인덱스) 자체가 세로 스크롤을 이동시키므로 사전 스크롤은 불필요.
    // 끝쪽 인덱스(예: 9) 호출 시 첫번째 Row 가 될 수 없으면 자동으로 최대 스크롤 위치로 보정됨(@spec1).
    target1.setTopRowIndex(topRowIndex, noEvent, autoFocus);

    // 이동은 렌더 의존값 → native setTimeout(500) 으로 갱신 후 읽음
    setTimeout(function () {
        let afterTop = target1.getTopRowIndex();
        let afterBottom = target1.getBottomRowIndex();

        // 포커스 위치 확인 (autoFocus 검증)
        let focusedTd = document.activeElement;
        let focusedCellId = (focusedTd && focusedTd.id) ? focusedTd.id : '(없음)';

        wf_body_bottom.getObj("scwin").setReturnValue(
            "setTopRowIndex(" + topRowIndex + ", noEvent=" + noEvent + ", autoFocus=" + autoFocus + ") 실행"
            + "\n[호출 전] getTopRowIndex() : " + beforeTop + " , getBottomRowIndex() : " + beforeBottom
            + "\n[호출 후] getTopRowIndex() : " + afterTop + " , getBottomRowIndex() : " + afterBottom
            + "\n해당 Row 가 첫번째 Row 로 표시됨(getTopRowIndex() == 설정값) : " + (afterTop === topRowIndex)
            + "\nonscrollend 발생 여부 : " + scwin.scrollEndFired
            + "\n실행 후 포커스 Cell id : " + focusedCellId
        );
    }, 500);
}
